  const rootRouteNode =
    routeNodes.find(
      (d) =>
        d.routePath === `/${rootPathId}` &&
        ![
          'component',
          'errorComponent',
          'notFoundComponent',
          'pendingComponent',
          'loader',
          'lazy',
        ].includes(d._fsRouteType),
    ) ?? routeNodes.find((d) => d.routePath === `/${rootPathId}`)
